css:
html, body { margin: 0; padding: 0; }
.print-format { margin: 0; padding: 0; margin-top: 0mm; margin-right: 0mm; margin-bottom: 0mm; margin-left: 0mm; page-size: A4; font-family: 'Sarabun', 'TH Sarabun New', 'Noto Sans Thai', Tahoma, sans-serif; font-size: 11pt; color: #000; }
.wht50-page { position: relative; width: 210mm; height: 296mm; overflow: hidden; page-break-after: always; }
.wht50-page:last-child { page-break-after: auto; }
.wht50-form { position: absolute; left: 0; top: 0; width: 210mm; height: 297mm; }
.wht50-page .f { position: absolute; white-space: nowrap; overflow: hidden; }
.wht50-page .c { text-align: center; }
.wht50-page .r { text-align: right; }
.wht50-page .cap { font-size: 8pt; }
.wht50-page .sm { font-size: 6.5pt; overflow: visible; }
.wht50-page .stamp { color: #b00; font-weight: bold; text-align: right; }
.wht50-page .tick { font-weight: bold; }

html:
{% set copies = [
    'ฉบับที่ 1 (สำหรับผู้ถูกหักภาษี ณ ที่จ่าย ใช้แนบพร้อมกับแบบแสดงรายการภาษี)',
    'ฉบับที่ 2 (สำหรับผู้ถูกหักภาษี ณ ที่จ่าย เก็บไว้เป็นหลักฐาน)',
    'ฉบับที่ 3 (สำหรับผู้หักภาษี ณ ที่จ่าย เก็บไว้เป็นหลักฐาน)'
] %}
{% set supplier = frappe.get_doc("Supplier", doc.supplier) if doc.supplier and not doc.employee else none %}
{% set payee_name = (doc.supplier_name or (supplier.supplier_name if supplier else "")) %}
{% if doc.is_agent and doc.withholding_agent_for_name %}{% set payee_name = payee_name ~ " (ในนามของ " ~ doc.withholding_agent_for_name ~ ")" %}{% endif %}
{% set payee_tax_id = doc.supplier_tax_id or (supplier.tax_id if supplier else "") %}
{% set total_base = doc.withholding_tax_items | sum(attribute='tax_base') %}
{% set total_tax = doc.withholding_tax_items | sum(attribute='tax_amount') %}
{% set CELLS_A = [['132.24', '4.07'], ['138.59', '4.19'], ['142.79', '4.19'], ['146.98', '4.19'], ['151.17', '4.19'], ['157.86', '4.24'], ['162.09', '4.24'], ['166.33', '4.24'], ['170.57', '4.24'], ['174.81', '4.24'], ['181.13', '4.24'], ['185.38', '4.24'], ['192.26', '4.07']] %}
{% set CELLS_B = [['132.44', '4.07'], ['138.80', '4.19'], ['142.99', '4.19'], ['147.18', '4.19'], ['151.38', '4.19'], ['158.06', '4.24'], ['162.30', '4.24'], ['166.54', '4.24'], ['170.77', '4.24'], ['175.01', '4.24'], ['181.34', '4.24'], ['185.58', '4.24'], ['192.47', '4.07']] %}
{% set ROWS = [("1", 108.76), ("2", 113.84), ("3", 118.98), ("4", 124.06), ("4.1.1", 144.59), ("4.1.2", 149.67), ("4.1.3", 154.76), ("4.1.4", 159.89), ("4.2.1", 170.15), ("4.2.2", 180.37), ("4.2.3", 190.59), ("4.2.4", 195.62), ("4.2.5", 200.75), ("5", 221.33), ("6", 226.42)] %}
{% set ID_H = 4.83 %}
{% set TEXT_H = 3.6 %}
{% set MONTHS = ['', 'มกราคม', 'กุมภาพันธ์', 'มีนาคม', 'เมษายน', 'พฤษภาคม', 'มิถุนายน', 'กรกฎาคม', 'สิงหาคม', 'กันยายน', 'ตุลาคม', 'พฤศจิกายน', 'ธันวาคม'] %}
{% macro address(address_name) %}
    {% if address_name %}{% set a = frappe.get_doc("Address", address_name) %}
    {% for part in [a.address_line1, a.address_line2, a.city, a.county, a.state, a.pincode] if part %}{{ part | e }}{% if not loop.last %} {% endif %}{% endfor %}{% endif %}
{% endmacro %}
{% macro payee_address_text() %}{% if doc.employee %}{{ (doc.employee_address or '') | e }}{% else %}{{ address(doc.supplier_address) }}{% endif %}{% endmacro %}
{% set payee_address = payee_address_text() %}
{# Buddhist-era date parts #}
{% macro thai_short(value) %}{% if value %}{% set d = value | str %}{{ d[8:10] }}/{{ d[5:7] }}/{{ (d[0:4] | int) + 543 }}{% endif %}{% endmacro %}
{% macro thai_day(value) %}{% if value %}{{ (value | str)[8:10] | int }}{% endif %}{% endmacro %}
{% macro thai_month(value) %}{% if value %}{{ MONTHS[(value | str)[5:7] | int] }}{% endif %}{% endmacro %}
{% macro thai_year(value) %}{% if value %}{{ ((value | str)[0:4] | int) + 543 }}{% endif %}{% endmacro %}
{% macro id_boxes(value, top, cells) %}{% set digits = [] %}{% for ch in (value or '') | str %}{% if ch in '0123456789' %}{% set _ = digits.append(ch) %}{% endif %}{% endfor %}{% if digits | length == 13 %}{% for cell in cells %}<div class="f c" style="left:{{ cell[0] }}mm;top:{{ top }}mm;width:{{ cell[1] }}mm;height:{{ ID_H }}mm;line-height:{{ ID_H }}mm">{{ digits[loop.index0] }}</div>{% endfor %}{% endif %}{% endmacro %}
{% macro money(value, bx0, bx1, sx0, sx1, y) %}{% set parts = ("{:.2f}".format(value or 0)).split(".") %}{% set whole = "{:,}".format(parts[0] | int) %}<div class="f r" style="left:{{ bx0 }}mm;top:{{ y - TEXT_H - 0.5 }}mm;width:{{ bx1 - bx0 }}mm;height:{{ TEXT_H }}mm;line-height:{{ TEXT_H }}mm">{{ whole }}</div><div class="f c" style="left:{{ sx0 }}mm;top:{{ y - TEXT_H - 0.5 }}mm;width:{{ sx1 - sx0 }}mm;height:{{ TEXT_H }}mm;line-height:{{ TEXT_H }}mm">{{ parts[1] }}</div>{% endmacro %}
{% for copy in copies %}
<div class="wht50-page">
<img class="wht50-form" src="/assets/erpnext/images/thailand/wht/WithholdingTaxCert.png">
<div class="f cap" style="left:9.91mm;top:3.2mm;width:152.47mm;height:5mm;line-height:5mm">{{ copy }}</div>
{% if doc.docstatus == 2 %}<div class="f cap stamp" style="left:140mm;top:3.2mm;width:60mm;height:5mm;line-height:5mm">ยกเลิก (Cancelled)</div>{% endif %}
<div class="f sm" style="left:180.93mm;top:21.31mm;width:19.31mm;height:3.6mm;line-height:3.6mm">{{ doc.name | e }}</div>
<div class="f " style="left:19.31mm;top:35.69mm;width:91.48mm;height:3.6mm;line-height:3.6mm">{{ doc.company | e }}</div>
<div class="f " style="left:20.33mm;top:43.93mm;width:172.80mm;height:3.6mm;line-height:3.6mm">{{ address(doc.company_address) | trim }}</div>
{{ id_boxes(doc.company_tax_id, 29.58, CELLS_A) }}
<div class="f " style="left:19.31mm;top:61.41mm;width:91.48mm;height:3.6mm;line-height:3.6mm">{{ payee_name | e }}</div>
<div class="f " style="left:20.33mm;top:70.61mm;width:172.80mm;height:3.6mm;line-height:3.6mm">{{ payee_address | trim }}</div>
{{ id_boxes(payee_tax_id, 53.82, CELLS_B) }}
<div class="f c" style="left:166.75mm;top:80.66mm;width:4.07mm;height:4.07mm;line-height:4.07mm">{% if doc.income_tax_form == 'PND3' %}X{% endif %}</div>
<div class="f c" style="left:139.56mm;top:87.16mm;width:4.07mm;height:4.07mm;line-height:4.07mm">{% if doc.income_tax_form == 'PND53' %}X{% endif %}</div>
{% for code, y in ROWS %}{% set items = doc.withholding_tax_items | selectattr('type_of_income', 'equalto', code) | list %}{% if items %}{% set base = items | sum(attribute='tax_base') %}{% set tax = items | sum(attribute='tax_amount') %}<div class="f c" style="left:116.89mm;top:{{ y - 4.1 }}mm;width:25.41mm;height:3.6mm;line-height:3.6mm">{{ thai_short(doc.date) }}</div>{{ money(base, 143.07, 166.19, 167.82, 172.39, y) }}{{ money(tax, 173.05, 191.60, 192.97, 197.40, y) }}{% if code in ['4.1.4', '4.2.5', '6'] %}<div class="f" style="left:{{ {"4.1.4": 40.66, "4.2.5": 51.84, "6": 33.03}[code] }}mm;top:{{ y - 4.1 }}mm;width:{{ {"4.1.4": 28.46, "4.2.5": 48.28, "6": 63.53}[code] }}mm;height:3.6mm;line-height:3.6mm">{{ (items | map(attribute="description") | select | join(", ")) | e }}</div>{% endif %}{% endif %}{% endfor %}
{{ money(total_base, 143.07, 166.19, 167.82, 172.39, 234.04) }}
{{ money(total_tax, 173.05, 191.60, 192.97, 197.40, 234.04) }}
<div class="f " style="left:63.53mm;top:236.55mm;width:132.14mm;height:3.6mm;line-height:3.6mm">{{ amount_in_bahttext("{:.2f}".format(total_tax)) | e }}</div>
<div class="f c" style="left:29.43mm;top:250.86mm;width:4.07mm;height:4.07mm;line-height:4.07mm">{% if doc.tax_payer == 'Withholding' %}X{% endif %}</div>
<div class="f c" style="left:62.26mm;top:250.86mm;width:4.07mm;height:4.07mm;line-height:4.07mm">{% if doc.tax_payer == 'Paid Continuously' %}X{% endif %}</div>
<div class="f c" style="left:100.27mm;top:250.86mm;width:4.07mm;height:4.07mm;line-height:4.07mm">{% if doc.tax_payer == 'Paid One Time' %}X{% endif %}</div>
<div class="f c" style="left:124.52mm;top:262.47mm;width:43.20mm;height:3.6mm;line-height:3.6mm">{{ frappe.get_fullname(doc.owner) | e }}</div>
<div class="f c" style="left:117.40mm;top:266.63mm;width:12.20mm;height:3.6mm;line-height:3.6mm">{{ thai_day(doc.date) }}</div>
<div class="f c" style="left:132.34mm;top:266.63mm;width:14.79mm;height:3.6mm;line-height:3.6mm">{{ thai_month(doc.date) }}</div>
<div class="f c" style="left:150.18mm;top:266.63mm;width:17.53mm;height:3.6mm;line-height:3.6mm">{{ thai_year(doc.date) }}</div>
</div>
{% endfor %}
